		if (eventName === "dailyQuestFarm" || eventName === "daysLogin" || action.includes("dailyquest") || action.includes("dayslogin")) return "daily";
		if (eventName === "energySpend" || eventName === "missionRaid") return "energy";
		if (eventName === "adventureBuffGet" || eventName === "adventureTowerDefeat" || mechanic === "adventure" || action.includes("adventure")) return "adventure";
		if (normalizedEventName.startsWith("tower") || mechanic === "tower" || action.includes("tower")) return "tower";
		if (mechanic === "mission" || eventName === "missionComplete" || action.includes("campaign") || action.includes("mission")) return "campaign";
		if (mechanic === "arena" || action.includes("arena") || action.includes("grandarena")) return "arena";
		if (eventName === "clanRaidNodeBattle" || action.includes("clanraid") || action.includes("raid")) return "dungeon";
		if (mechanic === "clan_dungeon" || normalizedEventName.startsWith("dungeon") || action.includes("dungeon")) return "dungeon";
		if (eventName === "heroEnchantRuneByType" || action.includes("rune")) return "rune";
		if (action.includes("titan")) return "titan";
		if (normalizedEventName.startsWith("hero") || eventName === "unitLevelUp" || action.includes("artifact") || action.includes("skin") || action.includes("skill") || action.includes("potion") || action.includes("ascension") || action.includes("soulstone") || action.includes("soulatrium")) return "hero";
